31	import com.example.starter.ticket.TicketDtos.StepSpec;
32	import com.example.starter.ticket.TicketDtos.StepView;
33	import com.example.starter.ticket.TicketDtos.TicketDetailView;
34	import com.example.starter.ticket.TicketDtos.TicketView;
35	
36	/**
37	 * 倒闸操作票核心服务：拟票→审核→预发→逐项执行→归档流转，
38	 * 双人确认、24 小时有效期、防误闭锁联动与归档终态。
39	 */
40	@Service
41	public class SwitchingOrderService {
42	
43	    /** 操作票自预发起的有效期：24 小时，恰满即作废。 */
44	    public static final Duration VALIDITY = Duration.ofHours(24);
45	
46	    private static final RowMapper<TicketRow> TICKET_MAPPER = (rs, rowNum) -> new TicketRow(
47	            rs.getLong("id"),
48	            rs.getString("request_id"),
49	            rs.getString("interval_id"),
50	            rs.getString("title"),
51	            rs.getString("status"),
52	            rs.getString("reviewer_id"),
53	            toInstant(rs.getTimestamp("issued_at")),
54	            toInstant(rs.getTimestamp("expires_at")),
55	            toInstant(rs.getTimestamp("created_at")),
56	            toInstant(rs.getTimestamp("updated_at")));
57	
58	    private static final RowMapper<StepRow> STEP_MAPPER = (rs, rowNum) -> new StepRow(
59	            rs.getLong("id"),
60	            rs.getInt("seq"),
61	            rs.getString("operation_type"),
62	            rs.getString("device_id"),
63	            rs.getString("expected_state"),
64	            rs.getString("status"),
65	            rs.getString("operator_id"),
66	            rs.getString("guardian_id"),
67	            toInstant(rs.getTimestamp("executed_at")),
68	            rs.getBoolean("verified"));
69	
70	    private final JdbcTemplate jdbc;
71	    private final Clock clock;
72	    private final InterlockService interlockService;
73	    private final TransactionTemplate requiresNewTx;
74	
75	    public SwitchingOrderService(JdbcTemplate jdbc, Clock businessClock, InterlockService interlockService,
76	                                 PlatformTransactionManager txManager) {
77	        this.jdbc = jdbc;
78	        this.clock = businessClock;
79	        this.interlockService = interlockService;
80	        this.requiresNewTx = new TransactionTemplate(txManager);
81	        this.requiresNewTx.setPropagationBehavior(
82	                org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);
83	    }
84	
85	    /** 拟票：创建 DRAFT 操作票及步骤。 */
86	    @Transactional
87	    public TicketDetailView create(CreateTicketRequest req) {
88	        Instant now = Instant.now(clock);
89	        KeyHolder keyHolder = new GeneratedKeyHolder();
90	        jdbc.update(con -> {
91	            PreparedStatement ps = con.prepareStatement(
92	                    "INSERT INTO switching_ticket (request_id, interval_id, title, status, created_at, updated_at)"
93	                            + " VALUES (?, ?, ?, 'DRAFT', ?, ?)",
94	                    Statement.RETURN_GENERATED_KEYS);
95	            ps.setString(1, req.requestId());
96	            ps.setString(2, req.intervalId());
97	            ps.setString(3, req.title());
98	            ps.setTimestamp(4, Timestamp.from(now));
99	            ps.setTimestamp(5, Timestamp.from(now));
100	            return ps;
101	        }, keyHolder);
102	        long ticketId = keyHolder.getKey().longValue();
103	        int seq = 1;
104	        for (StepSpec step : req.steps()) {
105	            jdbc.update(
106	                    "INSERT INTO switching_step (ticket_id, seq, operation_type, device_id, expected_state, status)"
107	                            + " VALUES (?, ?, ?, ?, ?, 'PENDING')",
108	                    ticketId, seq++, step.operationType(), step.deviceId(), step.expectedState());
109	        }
110	        return detail(ticketId);
111	    }
112	
113	    /** 审核：DRAFT → REVIEWED。 */
114	    @Transactional
115	    public TicketDetailView review(long ticketId, ReviewRequest req) {
116	        TicketRow ticket = mustLoad(ticketId);
117	        if (!"DRAFT".equals(ticket.status())) {
118	            throw ApiException.conflict("TICKET_STATE", "仅拟票状态可审核，当前状态: " + ticket.status());
119	        }
120	        jdbc.update("UPDATE switching_ticket SET status = 'REVIEWED', reviewer_id = ?, updated_at = ? WHERE id = ?",
121	                req.reviewerId(), Timestamp.from(Instant.now(clock)), ticketId);
122	        return detail(ticketId);
123	    }
124	
125	    /** 预发：REVIEWED → ISSUED，占用间隔执行锁，登记 24 小时有效期（UTC）。 */
126	    @Transactional
127	    public TicketDetailView issue(long ticketId, IssueRequest req) {
128	        TicketRow ticket = mustLoad(ticketId);
129	        if (!"REVIEWED".equals(ticket.status())) {
130	            throw ApiException.conflict("TICKET_STATE", "仅已审核状态可预发，当前状态: " + ticket.status());
131	        }
132	        Instant now = Instant.now(clock);
133	        try {
134	            jdbc.update("INSERT INTO interval_execution_lock (interval_id, ticket_id, acquired_at) VALUES (?, ?, ?)",
135	                    ticket.intervalId(), ticketId, Timestamp.from(now));
136	        } catch (DuplicateKeyException e) {
137	            throw ApiException.conflict("CONCURRENT_TICKET",
138	                    "间隔 " + ticket.intervalId() + " 已存在执行中操作票");
139	        }
140	        jdbc.update("UPDATE switching_ticket SET status = 'ISSUED', issued_at = ?, expires_at = ?, updated_at = ?"
141	                        + " WHERE id = ?",
142	                Timestamp.from(now), Timestamp.from(now.plus(VALIDITY)), Timestamp.from(now), ticketId);
143	        return detail(ticketId);
144	    }
145	
146	    /** 步骤双人确认：校验有效期、步序、双人确认与防误闭锁后执行一步。 */
147	    @Transactional
148	    public ConfirmView confirm(long ticketId, int seq, ConfirmStepRequest req) {
149	        TicketRow ticket = mustLoad(ticketId);
150	        refreshExpiry(ticket, true);
151	        if (!"ISSUED".equals(ticket.status()) && !"EXECUTING".equals(ticket.status())) {
152	            throw ApiException.conflict("TICKET_STATE", "仅预发或执行中状态可执行步骤，当前状态: " + ticket.status());
153	        }
154	        if (req.operatorId().equals(req.guardianId())) {
155	            throw ApiException.badRequest("DOUBLE_CONFIRM_REQUIRED", "操作人与监护人必须为两人，单人操作不生效");
156	        }
157	        StepRow step = jdbc.query("SELECT * FROM switching_step WHERE ticket_id = ? AND seq = ?",
158	                        STEP_MAPPER, ticketId, seq)
159	                .stream().findFirst()
160	                .orElseThrow(() -> ApiException.notFound("STEP_NOT_FOUND", "步骤不存在: " + seq));
161	        if (!"PENDING".equals(step.status())) {
162	            throw ApiException.conflict("STEP_STATE", "步骤已执行，当前状态: " + step.status());
163	        }
164	        Integer nextSeq = jdbc.query(
165	                        "SELECT MIN(seq) FROM switching_step WHERE ticket_id = ? AND status = 'PENDING'",
166	                        (rs, rowNum) -> rs.getInt(1), ticketId)
167	                .stream().findFirst().orElse(null);
168	        if (nextSeq == null || nextSeq != seq) {
169	            throw ApiException.conflict("STEP_ORDER", "须逐项执行，当前应执行步序: " + nextSeq);
170	        }
171	        InterlockResult interlock = interlockService.evaluate(step.operationType(), step.deviceId());
172	        if (interlock.blocked()) {
173	            interlockService.recordHit(ticketId, seq, interlock.ruleCode(), interlock.detail());
174	            throw ApiException.conflict("INTERLOCK_BLOCKED",
175	                    interlock.detail() + " [" + interlock.ruleCode() + "]");
176	        }
177	        Instant now = Instant.now(clock);
178	        jdbc.update("UPDATE switching_step SET status = 'DONE', operator_id = ?, guardian_id = ?, executed_at = ?"
179	                        + " WHERE id = ? AND status = 'PENDING'",
180	                req.operatorId(), req.guardianId(), Timestamp.from(now), step.id());
181	        jdbc.update("UPDATE device_state SET state = ?, updated_at = ? WHERE device_id = ?",
182	                step.expectedState(), Timestamp.from(now), step.deviceId());
183	        jdbc.update("UPDATE switching_ticket SET status = 'EXECUTING', updated_at = ? WHERE id = ?",
184	                Timestamp.from(now), ticketId);
185	        return new ConfirmView(ticketId, seq, "DONE", "EXECUTING");
186	    }
187	
188	    /** 归档：终态。重复归档返回幂等成功；到期票先转作废再归档。 */
189	    @Transactional
190	    public TicketDetailView archive(long ticketId, ArchiveRequest req) {
191	        TicketRow ticket = mustLoad(ticketId);
192	        if ("ARCHIVED".equals(ticket.status())) {
193	            return detail(ticketId);
194	        }
195	        ticket = refreshExpiry(ticket, false);
196	        switch (ticket.status()) {
197	            case "ISSUED", "EXECUTING", "EXCEPTION", "EXPIRED" -> {
198	                jdbc.update("UPDATE switching_ticket SET status = 'ARCHIVED', updated_at = ? WHERE id = ?",
199	                        Timestamp.from(Instant.now(clock)), ticketId);
200	                releaseLock(ticket.intervalId(), ticketId);
201	            }
202	            default -> throw ApiException.conflict("TICKET_STATE", "当前状态不可归档: " + ticket.status());
203	        }
204	        return detail(ticketId);
205	    }
206	
207	    /** 查询操作票详情：票、步序轨迹与闭锁命中。 */
208	    @Transactional(readOnly = true)
209	    public TicketDetailView get(long ticketId) {
210	        mustLoad(ticketId);
211	        return detail(ticketId);
212	    }
213	
214	    /**
215	     * 遥信核对：活动票最近一条已执行未核对步骤与回报比对，
216	     * 一致则标记核对，不符则中止操作票转异常并释放间隔锁。
217	     *
218	     * @return VERIFIED 核对一致 / ABORTED 不符中止 / RECORDED 仅记录
219	     */
220	    @Transactional
221	    public String processTelemetry(long ticketId, String deviceId, String state) {
222	        TicketRow ticket = mustLoad(ticketId);
223	        ticket = refreshExpiry(ticket, false);
224	        if (!"ISSUED".equals(ticket.status()) && !"EXECUTING".equals(ticket.status())) {
225	            return "RECORDED";
226	        }
227	        StepRow step = jdbc.query(
228	                        "SELECT * FROM switching_step WHERE ticket_id = ? AND status = 'DONE' AND verified = FALSE"
229	                                + " ORDER BY seq DESC LIMIT 1",
230	                        STEP_MAPPER, ticketId)
231	                .stream().findFirst().orElse(null);
232	        if (step == null || !step.deviceId().equals(deviceId)) {
233	            return "RECORDED";
234	        }
235	        if (step.expectedState().equals(state)) {
236	            jdbc.update("UPDATE switching_step SET verified = TRUE WHERE id = ?", step.id());
237	            return "VERIFIED";
238	        }
239	        jdbc.update("UPDATE switching_ticket SET status = 'EXCEPTION', updated_at = ? WHERE id = ?",
240	                Timestamp.from(Instant.now(clock)), ticketId);
241	        releaseLock(ticket.intervalId(), ticketId);
242	        return "ABORTED";
243	    }
244	
245	    /** 查询间隔当前执行中操作票主键，无则返回 null。 */
246	    public Long activeTicketForInterval(String intervalId) {
247	        return jdbc.query("SELECT ticket_id FROM interval_execution_lock WHERE interval_id = ?",
248	                        (rs, rowNum) -> rs.getLong(1), intervalId)
249	                .stream().findFirst().orElse(null);
250	    }
251	
252	    /** 判断间隔是否存在已归档操作票（用于迟到遥信标记）。 */
253	    public boolean hasArchivedTicket(String intervalId) {
254	        Integer count = jdbc.queryForObject(
255	                "SELECT COUNT(*) FROM switching_ticket WHERE interval_id = ? AND status = 'ARCHIVED'",
256	                Integer.class, intervalId);
257	        return count != null && count > 0;
258	    }
259	
260	    /**
261	     * 有效期检查：预发或执行中的票恰满 24 小时（UTC）即作废并释放间隔锁，已执行步骤保留。
262	     *
263	     * @param throwOnExpire 为 true 时作废后抛 409，为 false 时静默转作废
264	     */
265	    private TicketRow refreshExpiry(TicketRow ticket, boolean throwOnExpire) {
266	        boolean expirable = "ISSUED".equals(ticket.status()) || "EXECUTING".equals(ticket.status());
267	        if (expirable && ticket.expiresAt() != null && !Instant.now(clock).isBefore(ticket.expiresAt())) {
268	            // 作废转换独立事务提交：即使外层操作随后拒绝回滚，作废状态与锁释放仍生效
269	            requiresNewTx.executeWithoutResult(s -> {
270	                jdbc.update("UPDATE switching_ticket SET status = 'EXPIRED', updated_at = ? WHERE id = ?",
271	                        Timestamp.from(Instant.now(clock)), ticket.id());
272	                releaseLock(ticket.intervalId(), ticket.id());
273	            });
274	            if (throwOnExpire) {
275	                throw ApiException.conflict("TICKET_EXPIRED", "操作票自预发起已满24小时，恰满作废");
276	            }
277	            return mustLoad(ticket.id());
278	        }
279	        return ticket;
280	    }
281	
282	    private void releaseLock(String intervalId, long ticketId) {
283	        jdbc.update("DELETE FROM interval_execution_lock WHERE interval_id = ? AND ticket_id = ?",
284	                intervalId, ticketId);
285	    }
286	
287	    private TicketRow mustLoad(long ticketId) {
288	        return jdbc.query("SELECT * FROM switching_ticket WHERE id = ?", TICKET_MAPPER, ticketId)
289	                .stream().findFirst()
290	                .orElseThrow(() -> ApiException.notFound("TICKET_NOT_FOUND", "操作票不存在: " + ticketId));
291	    }
292	
293	    private TicketDetailView detail(long ticketId) {
294	        TicketRow ticket = mustLoad(ticketId);
295	        List<StepView> steps = jdbc.query("SELECT * FROM switching_step WHERE ticket_id = ? ORDER BY seq",
296	                        STEP_MAPPER, ticketId)
297	                .stream()
298	                .map(s -> new StepView(s.seq(), s.operationType(), s.deviceId(), s.expectedState(), s.status(),
299	                        s.operatorId(), s.guardianId(), s.executedAt(), s.verified()))
300	                .toList();
301	        List<HitView> hits = jdbc.query(
302	                        "SELECT * FROM interlock_hit WHERE ticket_id = ? ORDER BY id",
303	                        (rs, rowNum) -> new HitView(rs.getLong("id"),
304	                                rs.getObject("step_seq") == null ? null : rs.getInt("step_seq"),
305	                                rs.getString("rule_code"), rs.getString("detail"),
306	                                toInstant(rs.getTimestamp("created_at"))),
307	                        ticketId);
308	        TicketView view = new TicketView(ticket.id(), ticket.intervalId(), ticket.title(), ticket.status(),
309	                ticket.reviewerId(), ticket.issuedAt(), ticket.expiresAt(), ticket.createdAt(), ticket.updatedAt());
310	        return new TicketDetailView(view, steps, hits);
311	    }
312	
313	    private static Instant toInstant(Timestamp ts) {
314	        return ts == null ? null : ts.toInstant();
315	    }
316	
317	    /** 操作票行记录。 */
318	    record TicketRow(long id, String requestId, String intervalId, String title, String status,
319	                     String reviewerId, Instant issuedAt, Instant expiresAt,
320	                     Instant createdAt, Instant updatedAt) {
321	    }
322	
323	    /** 步骤行记录。 */
324	    record StepRow(long id, int seq, String operationType, String deviceId, String expectedState,
325	                   String status, String operatorId, String guardianId, Instant executedAt, boolean verified) {
326	    }
327	}
